    # Count the frequency of each tile
    tile_count = Counter(tiles)

    # Helper function to check if there's at least one shuntsu
    def has_shuntsu(count):
        return any(count[f'{i}{suit}'] >= 1 and count[f'{i+1}{suit}'] >= 1 and count[f'{i+2}{suit}'] >= 1 for i in range(8) for suit in 'mps')

    # Helper function to check if there's at least one koutsu
    def has_koutsu(count):
        return any(count[f'{i}{suit}'] >= 3 for i in range(1, 10) for suit in 'mps')

    # Check if the current set of tiles has any mentsu
    if has_shuntsu(tile_count) or has_koutsu(tile_count):
        return 0

    # If no mentsu, we need to draw enough tiles to form one
    needed = 0
    while not (has_shuntsu(tile_count) or has_koutsu(tile_count)):
        if has_shuntsu(tile_count):
            break
        if has_koutsu(tile_count):
            break
        needed += 1
        for i in range(1, 10):
            for suit in 'mps':
                tile_count[f'{i}{suit}'] += 1
                if has_shuntsu(tile_count) or has_koutsu(tile_count):
                    tile_count[f'{i}{suit}'] -= 1
                    break
            else:
                continue
            break
    return needed

