        return False

    # If there is already at least one mentsu, no additional tiles are needed
    if has_mentsu(tile_count):
        return 0

    # Otherwise, we need to find out how many tiles are missing to form at least one mentsu
    min_draws = float('inf')

    # Try to form a koutsu with each tile
    for tile, count in tile_count.items():
        if count < 3:
            missing = 3 - count
            remaining_tiles = {t: c for t, c in tile_count.items() if t != tile}
            if has_mentsu(remaining_tiles):
                min_draws = min(min_draws, missing)

    # Try to form a shuntsu with each starting tile
    for i in range(1, 8):
